import{z as s,x as i,o as e,c as d,q as t,j as n,D as a,d as B,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"跨期套利深化","description":"","frontmatter":{"title":"跨期套利深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-calendar-arb-deep.md","filePath":"quant/ft-calendar-arb-deep.md","lastUpdated":1791413859000}'),C={name:"quant/ft-calendar-arb-deep.md"};function p(u,E,D,F,m,c){const A=i("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="跨期套利深化" tabindex="-1">跨期套利深化 <a class="header-anchor" href="#跨期套利深化" aria-label="Permalink to &quot;跨期套利深化&quot;">​</a></h1><div class="epigraph"><p>被动展期缴纳当前斜率，跨期套利交易斜率的变化；深化从「带」开始——带由仓储上界、库存状态与交割期权共同写成，z-score 只是最后一步。</p><footer>—— Working, AER, 1949；价差波动与库存见 Ng and Pirrong, Journal of Business, 1994；交割选择权见 Gay and Manaster, JFE, 1984</footer></div><p><a href="/quant/ft-index-roll-strategy">上一课</a>把围绕指数基准的滚仓写成约束优化：被动展期按公开答案缴纳或收取斜率。有人要问斜率本身错没错，<a href="/quant/calendar-spread-arb">跨期套利</a>那一课已把基础写清：日历价差是仓储与便利收益的时间差分，内嵌近月的交割与挤仓期权。本课深化交易层：公允带怎么按状态定、偏离多少才是错价、蝶式怎么表达曲线二阶、组合层面怎么装。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基础课留下的缺口是「带」的定量化。持有成本给出上界：升水不能长期超过融资加仓储，否则现货买入加交割套利入场。下界没有同样的硬约束——空头现货做不成，贴水可以深而持久，便利收益 \\(y\\) 恰是缺口。深化的问题是：把这个非对称写成可操作的判定。错在哪：对日历价差套无条件 z-score，60 日均值里的 \\(y\\) 早变了；把带当成对称区间，在贴水端按「总会回到正持有费」加仓，等于做空便利收益与挤仓期权；忽略窗口——指数滚仓窗内价差被机械流量推离带，那是<a href="/quant/roll-volume-oi">展期成交量与持仓</a>的订单流，不是错价。</p><h3 id="带与状态的合写" tabindex="-1">带与状态的合写 <a class="header-anchor" href="#带与状态的合写" aria-label="Permalink to &quot;带与状态的合写&quot;">​</a></h3><p>公允带按状态写：</p> \\[\\underbrace{S_t\\big(\\mathrm{e}^{(r+u)\\tau_2}-\\mathrm{e}^{(r+u)\\tau_1}\\big)}_{\\text{全额持有成本上界}} \\;\\gt\\; F_2-F_1 \\;\\gt\\; \\underbrace{-\\,y(I)\\,S_t\\tau}_{\\text{随库存分位变化的下界}}, \\]<p>库存紧、\\(y\\) 高，下界深、带宽；库存松、\\(y\\) 趋零，带收窄到仓储加融资附近。开仓判定因此是三段：价差在带外；库存状态与方向矛盾（高库存却深度贴水，先排除挤仓与交割地局部短缺）；不在滚仓窗与交割窗内。三段有一段不满足，z-score 再高也不动手。</p><p><span class="marginnote">数字实例：设现货 4000 元/吨、年化融资加仓储 6%、远月比近月晚 3 个月，带上界约为 \\(4000 \\times 6\\% \\times 3/12 = 60\\) 元/吨。远月只贵 20 元时仍在带内，动手只会白付手续费；要贵过 60 元，买现货抛远月才有的赚。</span></p><p><span class="marginnote">蝶式（买近、卖中、买远）交易曲线二阶：对融资 \\(r\\) 的平移不敏感，对中间月份的流动性极度敏感。中腿常是最薄的合约，蝶式的理论价值差会先被中腿价差吃掉——容量按三腿中最小者再折半。</span></p><p><span class="marginnote">直觉类比：便利收益是「手里有货」的保险费。工厂库存满仓时多囤一吨原料没什么用，\\(y\\) 趋近零；缺货时，手里那一吨能保住产线不停转，\\(y\\) 飙升。深贴水正是市场为「马上要货的人」支付的价格，不是总能白捡的便宜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，状态条件化的参照：用第四课的状态表选 \\(y(I)\\) 的当期估计，而不是历史平均。第二步，信号：带外加状态矛盾，才进入候选；方向上，买贴水深化前的近月（低库存、\\(y\\) 高）与买升水过顶后的远月（高库存、带顶破）是两类不同的仓，后者受仓储套利约束更强、收敛更可依赖。第三步，风险账本：日历价差的保证金优惠放大杠杆，风险限额按两条计——近月腿的独立冲击与价差本身的冲击，交割月临近按日强制减仓。第四步，退出：收敛到带内、或状态反转（仓单注销、报告意外），而不是拿到固定目标价。</p>',14)),(e(),n(o,null,{default:a(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E5%BA%93%E5%AD%98%E5%88%86%E4%BD%8D%20%2F%20%E4%BB%93%E5%8D%95%20%2F%20%E7%AA%97%E5%8F%A3%E6%97%A5%E5%8E%86%22%5D%20--%3E%20BAND%5B%22%E5%85%AC%E5%85%81%E5%B8%A6%EF%BC%9A%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E4%B8%8A%E7%95%8C%20%2B%20y(I)%20%E4%B8%8B%E7%95%8C%22%5D%0A%20%20BAND%20--%3E%20Q1%7B%22%E4%BB%B7%E5%B7%AE%E5%9C%A8%E5%B8%A6%E5%A4%96%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20WAIT%5B%22%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20Q2%7B%22%E5%BA%93%E5%AD%98%E7%8A%B6%E6%80%81%E4%B8%8E%E6%96%B9%E5%90%91%E7%9F%9B%E7%9B%BE%EF%BC%9F%E6%8E%92%E9%99%A4%E6%8C%A4%E4%BB%93%22%7D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20WAIT%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20Q3%7B%22%E4%B8%8D%E5%9C%A8%E6%BB%9A%E4%BB%93%E7%AA%97%20%2F%20%E4%BA%A4%E5%89%B2%E7%AA%97%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%E5%90%A6%7C%20WAIT%0A%20%20Q3%20--%3E%7C%E6%98%AF%7C%20OPEN%5B%22%E5%BC%80%E4%BB%93%EF%BC%9A%E5%8F%8C%E9%99%90%E9%A2%9D%EF%BC%88%E8%BF%91%E6%9C%88%E7%8B%AC%E7%AB%8B%20%2B%20%E4%BB%B7%E5%B7%AE%EF%BC%89%22%5D%0A%20%20OPEN%20--%3E%20EXIT%5B%22%E9%80%80%E5%87%BA%EF%BC%9A%E5%B8%A6%E5%86%85%E6%94%B6%E6%95%9B%E6%88%96%E7%8A%B6%E6%80%81%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[B("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,"带非对称的机制是可空性：持有成本套利需要买现货空期货，多头方向带硬；反向需要空现货，商品现货借不出，贴水端只有软约束——Gay 与 Manaster 的品质与交割选择权给近月空头补了一层期权价值，让近月在贴水端还带着「接货义务」的定价。收敛的机制是仓储资本与交割，不是协整：带外偏离要靠有人真把货运进仓库、或真把仓单交割掉才闭合，资本进不来的偏离可以持久——这正是 Ng 与 Pirrong 的低库存、高价差波动世界的另一面。窗口机制把两类偏离分开：滚仓窗内的偏离是暂时成分，窗后回归；库存驱动的偏离是状态成分，报告日跳跃——两类混在一个均值里，回测的「回归速度」就是两个时钟的乱拍。",-1)),(e(),n(o,null,{default:a(()=>[l(A,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E5%8D%87%E6%B0%B4%E8%B6%8A%E8%BF%87%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E4%B8%8A%E7%95%8C%22%5D%20--%3E%20LB%5B%22%E4%B9%B0%E7%8E%B0%E8%B4%A7%20%2B%20%E7%A9%BA%E8%BF%9C%E6%9C%88%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20LB%20--%3E%20LOK%5B%22%E7%8E%B0%E8%B4%A7%E4%B9%B0%E5%BE%97%E5%88%B0%E3%80%81%E4%BB%93%E5%BA%93%E7%A7%9F%E5%BE%97%E5%88%B0%22%5D%0A%20%20LOK%20--%3E%20LEND%5B%22%E5%A5%97%E5%88%A9%E8%B5%84%E9%87%91%E5%85%A5%E5%9C%BA%EF%BC%9A%E5%81%8F%E7%A6%BB%E5%BE%88%E5%BF%AB%E9%97%AD%E5%90%88%EF%BC%8C%E4%B8%8A%E7%95%8C%E6%98%AF%E7%A1%AC%E7%9A%84%22%5D%0A%20%20DN%5B%22%E8%B4%B4%E6%B0%B4%E7%AA%81%E7%A0%B4%E4%B8%8B%E7%95%8C%22%5D%20--%3E%20SB%5B%22%E9%9C%80%E8%A6%81%E5%80%9F%E5%85%A5%E5%B9%B6%E5%8D%96%E7%A9%BA%E7%8E%B0%E8%B4%A7%22%5D%0A%20%20SB%20--%3E%20SNO%5B%22%E5%95%86%E5%93%81%E7%8E%B0%E8%B4%A7%E5%80%9F%E4%B8%8D%E5%87%BA%EF%BC%8C%E5%8F%8D%E5%90%91%E5%A5%97%E5%88%A9%E8%B5%B0%E4%B8%8D%E9%80%9A%22%5D%0A%20%20SNO%20--%3E%20SEND%5B%22%E5%81%8F%E7%A6%BB%E5%8F%AF%E4%BB%A5%E6%8C%81%E4%B9%85%EF%BC%8C%E4%B8%8B%E7%95%8C%E6%98%AF%E8%BD%AF%E7%9A%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者看到深度贴水就当作普通均值回归「越跌越买」。带外 z-score 只是三段判定的第一段——60 日均值里库存状态早已换过几轮，贴水端加仓实际是在做空便利收益与挤仓期权，方向错了止损空间也软。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨板块不是同一套带：金属有仓库与租借率，能源看管道与库容，农产品分新旧作，国债期货的「价差」还叠着 CTD 切换，见<a href="/quant/ctd-cheapest">最便宜可交割</a>。数据要在 vintage 上算，仓单与库存的修订会把「意外」改写掉。交割月不开新仓是铁律，蝶式的中腿进交割月同样触发。本课不写价差的下单方式与摊薄——那是<a href="/quant/ft-roll-execution">移仓的执行</a>的方案族，套利与展期共用一本执行账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公允带非对称：上界是持有成本，下界随 \\(y(I)\\) 走；贴水端的软约束是深化的核心。</li><li>开仓三段判定：带外、状态矛盾排除挤仓、避开滚仓窗与交割窗；z-score 是最后一步。</li><li>蝶式表达二阶，容量按中腿流动性折半；保证金优惠用双限额对冲掉。</li><li>收敛靠仓储资本与交割；窗口偏离与库存偏离分开归因，不共用一个回归速度。</li><li>出处：Working, <em>AER</em>, 1949；Ng and Pirrong, <em>Journal of Business</em>, 1994；Gay and Manaster, <em>JFE</em>, 1984。</li></ul>',5))])}const _=s(C,[["render",p]]);export{f as __pageData,_ as default};
